#!/usr/bin/env python3
"""microbiome/da_compositional_real — auto-generated run.py (archetype=microbiome_pipeline).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "microbiome_pipeline"
BRAIN = "microbiome"
SKILL = "da_compositional_real"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'da_compositional_real', 'n_samples': 0, 'taxonomy_table': '', 'diversity_metrics': {'shannon': 0.0, 'observed_otus': 0}, 'diagnostics': {'brain': 'microbiome', 'archetype': 'microbiome_pipeline'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """Differential abundance via ANCOMBC/Maaslin2 R。host_env=praxis-microbiome-da-v2。
    输入:abundance_csv (rows=samples, cols=taxa) / metadata_csv / group_col / method (ancombc|maaslin2)
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    abun = payload.get("abundance_csv")
    meta = payload.get("metadata_csv")
    group = payload.get("group_col", "group")
    method = payload.get("method", "ancombc")
    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="da_")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tool": method, "out_dir": out_dir}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "n_samples": 0, "taxonomy_table": "",
                "diversity_metrics": {"shannon": 0.0, "observed_otus": 0},
                "diagnostics": {**diagnostics, "dry": True}}
    if not abun or not _os.path.isfile(abun) or not meta or not _os.path.isfile(meta):
        return {"ok": False, "error": "需要 abundance_csv + metadata_csv 文件",
                "diagnostics": diagnostics}
    _os.makedirs(out_dir, exist_ok=True)
    out_csv = _os.path.join(out_dir, "da_results.csv")
    # R 脚本用占位符 + .format,避免 f-string 与 R 双引号转义冲突
    if method == "maaslin2":
        r_template = """library(Maaslin2)
abun <- read.csv('__ABUN__', row.names=1)
meta <- read.csv('__META__', row.names=1)
fit <- Maaslin2(input_data=abun, input_metadata=meta, output='__OUTDIR__',
                fixed_effects='__GROUP__', plot_heatmap=FALSE, plot_scatter=FALSE)
write.csv(fit$results, '__OUTCSV__', row.names=FALSE)
cat(sprintf('OK n_results=%d', nrow(fit$results)))
"""
    else:
        r_template = """library(ANCOMBC)
library(phyloseq)
abun <- as.matrix(read.csv('__ABUN__', row.names=1))
meta <- read.csv('__META__', row.names=1)
ps <- phyloseq(otu_table(abun, taxa_are_rows=FALSE), sample_data(meta))
out <- ancombc2(data=ps, fix_formula='__GROUP__', p_adj_method='BH')
write.csv(out$res, '__OUTCSV__', row.names=FALSE)
cat(sprintf('OK n_results=%d', nrow(out$res)))
"""
    r_script = (r_template
                .replace("__ABUN__", abun)
                .replace("__META__", meta)
                .replace("__OUTDIR__", out_dir)
                .replace("__GROUP__", group)
                .replace("__OUTCSV__", out_csv))
    rscript_path = _os.path.join(out_dir, "_da.R")
    with open(rscript_path, "w") as fh: fh.write(r_script)
    t0 = _time.time()
    r = run_tool(["Rscript", rscript_path], timeout=int(payload.get("timeout_s", 1800)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", f"{method} R 失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}
    # 从 stdout 抓 'OK n_results=N'
    n_results = 0
    for ln in reversed(r["stdout"].splitlines()):
        if "n_results=" in ln:
            try:
                n_results = int(ln.split("n_results=")[1].split()[0])
                break
            except (ValueError, IndexError):
                continue
    return {"ok": True, "skill_id": SKILL, "n_samples": 0,
            "taxonomy_table": out_csv,
            "diversity_metrics": {"shannon": 0.0, "observed_otus": n_results},
            "runtime_sec": round(_time.time() - t0, 2), "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
